import { Component, OnInit, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../core/api.service';
import { Certificate, Volunteer } from '../core/models';
import { environment } from '../../environments/environment';

interface Row { volunteer: Volunteer; hours: number; }

/**
 * FR-09 — Certificates of Appreciation. The PDF is generated by the server
 * from accumulated service hours; a volunteer below the threshold is shown
 * with how far they still have to go rather than being hidden.
 */
@Component({
  selector: 'bp-certificates', standalone: true, imports: [CommonModule, FormsModule],
  template: `
    <div class="head">
      <div>
        <h1>Certificates</h1>
        <p class="muted small">Certificates of Appreciation are issued from logged service hours.
           The minimum is {{ minimum }} hours.</p>
      </div>
    </div>

    <div class="body">
      @if (flash()) { <div class="notice notice-ok">{{ flash() }}</div> }
      @if (error()) { <div class="notice notice-error">{{ error() }}</div> }

      <div class="card">
        <div class="card-head"><h3>Approved volunteers</h3></div>
        <div class="card-body tight">
          @if (loading()) { <p class="spinner">Loading…</p> }
          @else if (rows().length === 0) {
            <p class="muted small pad">No approved volunteers yet.</p>
          } @else {
            <table>
              <thead>
                <tr><th>Volunteer</th><th>Area of service</th><th>Hours</th>
                    <th>Certificates issued</th><th></th></tr>
              </thead>
              <tbody>
                @for (r of rows(); track r.volunteer._id) {
                  <tr>
                    <td><strong>{{ r.volunteer.full_name }}</strong>
                        <span class="small muted">{{ r.volunteer.email }}</span></td>
                    <td class="small">{{ r.volunteer.area_of_service }}</td>
                    <td>
                      <strong class="h">{{ r.hours }}</strong>
                      @if (r.hours < minimum) {
                        <span class="small muted">{{ minimum - r.hours }} more needed</span>
                      }
                    </td>
                    <td>
                      @if (r.volunteer.certificates.length === 0) {
                        <span class="small muted">None</span>
                      }
                      @for (c of r.volunteer.certificates; track c._id) {
                        <a class="cert" [href]="url(c)" target="_blank" rel="noopener">
                          {{ c.date_issued | date: 'MMM d, y' }} · {{ c.total_hours }} hrs</a>
                      }
                    </td>
                    <td class="nowrap">
                      @if (r.hours >= minimum) {
                        <button class="btn btn-secondary btn-sm" [disabled]="busy()"
                                (click)="issue(r)">Generate PDF</button>
                      } @else {
                        <span class="small muted">Not yet eligible</span>
                      }
                    </td>
                  </tr>
                }
              </tbody>
            </table>
          }
        </div>
      </div>

      <p class="small muted note">Regenerating produces a second certificate rather than replacing
         the first, so a volunteer who comes back for another season keeps both records. The hours
         on each certificate are the total at the moment it was issued.</p>
    </div>
  `,
  styles: [`
    .head { background: #fff; border-bottom: 1px solid var(--line); padding: 20px 32px; }
    .head h1 { font-size: 26px; margin-bottom: 2px; }
    .head p { margin: 0; max-width: 75ch; }
    .body { padding: 22px 32px 40px; }
    .card-head h3 { font-family: var(--serif); font-size: 18px; margin: 0; }
    .card-body.tight { padding: 0; overflow-x: auto; }
    .pad { padding: 16px 18px; }
    table { width: 100%; border-collapse: collapse; font-size: 13px; }
    th { text-align: left; font-size: 10px; letter-spacing: .08em; text-transform: uppercase;
         color: var(--muted); padding: 11px 14px; background: var(--paper);
         border-bottom: 1px solid var(--line); white-space: nowrap; }
    td { padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: top; }
    tr:last-child td { border-bottom: 0; }
    td strong { display: block; }
    td span.small { display: block; }
    .h { font-family: var(--serif); font-size: 17px; color: var(--brand); }
    .cert { display: block; font-size: 12px; font-weight: 600; margin-bottom: 2px; }
    .btn-sm { padding: 6px 12px; font-size: 12px; }
    .nowrap { white-space: nowrap; }
    .note { margin-top: 14px; max-width: 80ch; }
    @media (max-width: 900px) { .head, .body { padding-left: 18px; padding-right: 18px; } }
  `],
})
export class CertificatesComponent implements OnInit {
  private api = inject(ApiService);

  /** Mirrors CERTIFICATE_MIN_HOURS on the server; the server is the authority. */
  readonly minimum = 20;

  rows = signal<Row[]>([]);
  loading = signal(true); busy = signal(false);
  flash = signal(''); error = signal('');

  ngOnInit(): void { this.load(); }

  load(): void {
    this.loading.set(true);
    this.api.volunteers({ status: 'Approved' }).subscribe({
      next: list => {
        this.rows.set(list.map(v => ({ volunteer: v, hours: 0 })));
        this.loading.set(false);
        // Hours live on the activity records, so each profile is fetched for its total.
        list.forEach(v => this.api.volunteer(v._id).subscribe({
          next: res => this.rows.update(rs => rs.map(r =>
            r.volunteer._id === v._id ? { volunteer: res.volunteer, hours: res.total_hours } : r)),
          error: () => {},
        }));
      },
      error: err => { this.error.set(err?.error?.message || 'Could not load volunteers.'); this.loading.set(false); },
    });
  }

  url(c: Certificate): string {
    return `${environment.apiUrl.replace(/\/api$/, '')}/${String(c.file_path || '').replace(/^\//, '')}`;
  }

  issue(r: Row): void {
    this.busy.set(true); this.error.set(''); this.flash.set('');
    this.api.generateCertificate(r.volunteer._id).subscribe({
      next: res => {
        this.flash.set(`Certificate generated for ${r.volunteer.full_name} — ${res.certificate.total_hours} hours.`);
        this.busy.set(false);
        this.load();
      },
      error: err => {
        this.error.set(err?.error?.message || 'Could not generate the certificate.');
        this.busy.set(false);
      },
    });
  }
}
